// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type ConversationWorldProps = Record<string, any>;

const ConversationWorld: React.FC<ConversationWorldProps> = ({
  backgroundColor = "#030712",
  transparentBackground = false,
  durationInSeconds = 10,
  primaryColor = "#38bdf8",
  secondaryColor = "#a855f7",
  mainText = "Have a conversation with the world around us.",
  subText = "Every signal sent creates a ripple. Every echo heard shifts the frequency of tomorrow. We are continuously shaping and being shaped by the interconnected web of our environment.",
  nodeCount = 36,
  connectionThreshold = 180,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive typography sizing
  const minDimension = Math.min(width, height);
  const mainFontSize = minDimension * 0.075;
  const subFontSize = minDimension * 0.024;

  // Generate nodes deterministically
  const { nodes, interConnections } = useMemo(() => {
    const minRadius = 120;
    const maxRadius = minDimension * 0.42;
    const generatedNodes = Array.from({ length: nodeCount }).map((_, i) => {
      const angle = random(`angle-${i}`) * Math.PI * 2;
      const distance = random(`dist-${i}`) * (maxRadius - minRadius) + minRadius;
      const size = random(`size-${i}`) * 12 + 6;
      
      return {
        id: i,
        x: Math.cos(angle) * distance,
        y: Math.sin(angle) * distance,
        size,
        angle,
        distance,
        // Assign deterministic timings for the "conversation" packets
        sendOffset: Math.floor(random(`send-${i}`) * 60) + 20,
        receiveOffset: Math.floor(random(`receive-${i}`) * 60) + 100,
      };
    });

    const connections: { a: typeof generatedNodes[0]; b: typeof generatedNodes[0] }[] = [];
    for (let i = 0; i < generatedNodes.length; i++) {
      for (let j = i + 1; j < generatedNodes.length; j++) {
        const dx = generatedNodes[i].x - generatedNodes[j].x;
        const dy = generatedNodes[i].y - generatedNodes[j].y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < connectionThreshold) {
          connections.push({ a: generatedNodes[i], b: generatedNodes[j] });
        }
      }
    }

    return { nodes: generatedNodes, interConnections: connections };
  }, [nodeCount, minDimension, connectionThreshold]);

  // Global animations
  const networkOpacity = interpolate(frame, [15, 60], [0, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const centerPulseScale = 1 + Math.sin(frame / 12) * 0.1;

  const words = mainText.split(/\s+/);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, flexDirection: "row", overflow: "hidden" }}>
      
      {/* LEFT PANE - TYPOGRAPHY */}
      <div
        style={{
          width: "45%",
          height: "100%",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          paddingLeft: "6%",
          paddingRight: "4%",
          zIndex: 10,
        }}
      >
        <h1
          style={{
            fontFamily: playfairFamily,
            fontSize: mainFontSize,
            lineHeight: 1.15,
            color: "#ffffff",
            margin: 0,
            display: "flex",
            flexWrap: "wrap",
            marginBottom: "2rem",
          }}
        >
          {words.map((word, i) => {
            const wordProgress = spring({
              frame: frame - i * 4,
              fps,
              config: { damping: 14, mass: 0.8 },
            });
            const yOffset = interpolate(wordProgress, [0, 1], [120, 0]);
            const wordOpacity = interpolate(wordProgress, [0, 0.5, 1], [0, 1, 1]);

            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  overflow: "hidden",
                  paddingBottom: "0.15em",
                  marginRight: "0.25em",
                }}
              >
                <span
                  style={{
                    display: "inline-block",
                    transform: `translateY(${yOffset}%)`,
                    opacity: wordOpacity,
                  }}
                >
                  {word}
                </span>
              </span>
            );
          })}
        </h1>

        <p
          style={{
            fontFamily: interFamily,
            fontSize: subFontSize,
            lineHeight: 1.6,
            color: "rgba(255, 255, 255, 0.7)",
            margin: 0,
            maxWidth: "90%",
            opacity: interpolate(frame, [40, 80], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }),
            transform: `translateY(${interpolate(frame, [40, 80], [20, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}px)`,
          }}
        >
          {subText}
        </p>
      </div>

      {/* RIGHT PANE - THE "WORLD" VISUALIZATION */}
      <div
        style={{
          width: "55%",
          height: "100%",
          position: "relative",
        }}
      >
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: 0,
            height: 0,
          }}
        >
          {/* SVG Layer for Connections */}
          <svg
            style={{
              position: "absolute",
              overflow: "visible",
              top: 0,
              left: 0,
            }}
          >
            {/* Direct Connections to Center */}
            <g opacity={networkOpacity}>
              {nodes.map((n, i) => {
                const drawProgress = spring({
                  frame: frame - 10 - i,
                  fps,
                  config: { damping: 50 },
                });
                const x2 = interpolate(drawProgress, [0, 1], [0, n.x]);
                const y2 = interpolate(drawProgress, [0, 1], [0, n.y]);
                return (
                  <line
                    key={`center-${i}`}
                    x1={0}
                    y1={0}
                    x2={x2}
                    y2={y2}
                    stroke={primaryColor}
                    strokeWidth={1}
                    opacity={0.3}
                  />
                );
              })}
            </g>

            {/* Inter-node Web Connections */}
            <g opacity={networkOpacity * 0.6}>
              {interConnections.map((conn, i) => {
                const drawProgress = spring({
                  frame: frame - 40 - i * 0.1,
                  fps,
                  config: { damping: 100 },
                });
                const currentX2 = interpolate(drawProgress, [0, 1], [conn.a.x, conn.b.x]);
                const currentY2 = interpolate(drawProgress, [0, 1], [conn.a.y, conn.b.y]);
                return (
                  <line
                    key={`web-${i}`}
                    x1={conn.a.x}
                    y1={conn.a.y}
                    x2={currentX2}
                    y2={currentY2}
                    stroke={secondaryColor}
                    strokeWidth={0.5}
                    opacity={0.4}
                  />
                );
              })}
            </g>
          </svg>

          {/* Central Node (The Self / Observer) */}
          <div
            style={{
              position: "absolute",
              left: -30,
              top: -30,
              width: 60,
              height: 60,
              backgroundColor: primaryColor,
              borderRadius: "50%",
              boxShadow: `0 0 50px ${primaryColor}, inset 0 0 20px #ffffff`,
              transform: `scale(${centerPulseScale})`,
              zIndex: 2,
            }}
          />

          {/* Outer Nodes (The World) */}
          {nodes.map((n, i) => {
            const floatY = Math.sin((frame + i * 15) / 40) * 12;
            const nodeScale = spring({
              frame: frame - 30 - i * 1.5,
              fps,
              config: { damping: 14 },
            });

            return (
              <div
                key={`node-${i}`}
                style={{
                  position: "absolute",
                  left: n.x - n.size / 2,
                  top: n.y + floatY - n.size / 2,
                  width: n.size,
                  height: n.size,
                  backgroundColor: i % 3 === 0 ? primaryColor : secondaryColor,
                  borderRadius: "50%",
                  boxShadow: `0 0 12px ${i % 3 === 0 ? primaryColor : secondaryColor}`,
                  transform: `scale(${nodeScale})`,
                  opacity: nodeScale,
                }}
              />
            );
          })}

          {/* "Conversation" Packets (Data flow animations) */}
          {nodes.map((n, i) => {
            // Loop the packets slightly by running multiple overlapping instances
            return [0, 120, 240].map((loopOffset) => {
              const currentSendStart = n.sendOffset + loopOffset;
              const currentRecvStart = n.receiveOffset + loopOffset;

              const sendProg = interpolate(frame, [currentSendStart, currentSendStart + 40], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });
              const recvProg = interpolate(frame, [currentRecvStart, currentRecvStart + 40], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              });

              return (
                <React.Fragment key={`packet-${i}-${loopOffset}`}>
                  {/* Outgoing Packet (Center -> Node) */}
                  {sendProg > 0 && sendProg < 1 && (
                    <div
                      style={{
                        position: "absolute",
                        left: interpolate(sendProg, [0, 1], [0, n.x]) - 4,
                        top: interpolate(sendProg, [0, 1], [0, n.y]) - 4,
                        width: 8,
                        height: 8,
                        backgroundColor: secondaryColor,
                        borderRadius: "50%",
                        boxShadow: `0 0 15px ${secondaryColor}, 0 0 5px #ffffff`,
                        opacity: Math.sin(sendProg * Math.PI), // Fades in and out organically along the path
                      }}
                    />
                  )}
                  {/* Incoming Packet (Node -> Center) */}
                  {recvProg > 0 && recvProg < 1 && (
                    <div
                      style={{
                        position: "absolute",
                        left: interpolate(recvProg, [0, 1], [n.x, 0]) - 4,
                        top: interpolate(recvProg, [0, 1], [n.y, 0]) - 4,
                        width: 8,
                        height: 8,
                        backgroundColor: primaryColor,
                        borderRadius: "50%",
                        boxShadow: `0 0 15px ${primaryColor}, 0 0 5px #ffffff`,
                        opacity: Math.sin(recvProg * Math.PI),
                      }}
                    />
                  )}
                </React.Fragment>
              );
            });
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ConversationWorld;